{
    "name": "@cristochang/opencode-spec",
    "version": "0.1.1",
    "description": "Unified spec package for OpenCode (Core + Execution + Integration + Tools)",
    "type": "module",
    "main": "./dist/index.js",
    "types": "./dist/index.d.ts",
    "exports": {
        ".": {
            "types": "./dist/index.d.ts",
            "import": "./dist/index.js"
        }
    },
    "files": [
        "dist",
        "README.md",
        "LICENSE"
    ],
    "scripts": {
        "build": "bun run build:js && bun run build:dts",
        "build:js": "bunx esbuild src/index.ts --bundle --platform=node --format=esm --outfile=dist/index.js --external:@opencode-ai/plugin --external:zod --external:ulid",
        "build:dts": "bunx tsc --emitDeclarationOnly",
        "test": "bun test"
    },
    "keywords": [
        "opencode",
        "opencode-plugin",
        "spec",
        "workflow"
    ],
    "author": "OpenCode",
    "license": "MIT",
    "peerDependencies": {
        "@opencode-ai/plugin": "^1.1.23"
    },
    "dependencies": {
        "ulid": "^3.0.0",
        "zod": "^4.0.0"
    },
    "devDependencies": {
        "@opencode-ai/plugin": "workspace:*",
        "@types/node": "22.13.9",
        "esbuild": "0.27.2",
        "typescript": "^5.0.0"
    },
    "engines": {
        "node": ">=18.0.0"
    }
}
